import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import "./index.css";

import HomePage from "./landing_page/home/HomePage";
import Signup from "./landing_page/signup/Signup.js";
import AboutPage from "./landing_page/about/AboutPage";
import ProductPage from "./landing_page/products/ProductsPage";
import PricingPage from "./landing_page/pricing/PricingPage";
import SupportPage from "./landing_page/support/SupportPage";

import NotFound from "./landing_page/NotFound";
import Navbar from "./landing_page/Navbar";
import Footer from "./landing_page/Footer";
import AuthSignup from "./auth/Signup";
import AuthLogin from "./auth/Login";
import AppHome from "./auth/Home";

// Sanity-check imports to show a helpful error instead of the generic React crash
const _imports = { HomePage, Signup, AboutPage, ProductPage, PricingPage, SupportPage, NotFound, Navbar, Footer, AuthSignup, AuthLogin, AppHome };
const invalid = Object.entries(_imports).filter(([, v]) => v === undefined || v === null);
if (invalid.length > 0) {
  const names = invalid.map(([k]) => k).join(", ");
  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    React.createElement(
      "div",
      { style: { padding: 24, fontFamily: "sans-serif" } },
      React.createElement("h2", null, "Import error"),
      React.createElement("p", null, `The following imports are undefined: ${names}`),
      React.createElement("pre", null, JSON.stringify(invalid.map(([k]) => k), null, 2))
    )
  );
  // stop further rendering
  throw new Error(`Undefined imports: ${names}`);
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <BrowserRouter>
    <Navbar />
    <Routes>
      <Route path="/" element={<HomePage />} />
      <Route path="/signup" element={<Signup />} />
      <Route path="/auth/signup" element={<AuthSignup />} />
      <Route path="/auth/login" element={<AuthLogin />} />
      <Route path="/app/home" element={<AppHome />} />
      <Route path="/about" element={<AboutPage />} />
      <Route path="/product" element={<ProductPage />} />
      <Route path="/pricing" element={<PricingPage />} />
      <Route path="/support" element={<SupportPage />} />
      <Route path="*" element={<NotFound />} />
    </Routes>
    <Footer />
  </BrowserRouter>
);
